-- Fixtures de metadatos: jamás llama ni elimina vídeos reales de Bunny.
begin;
set local statement_timeout='90s';
do $$
declare actor uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();claims jsonb;op uuid:=gen_random_uuid();create_claim uuid:=gen_random_uuid();
 reserved uuid;processing uuid;ready uuid;uncertain uuid;uncertain_alias uuid;guid_a uuid:=gen_random_uuid();guid_b uuid:=gen_random_uuid();guid_c uuid:=gen_random_uuid();guid_d uuid:=gen_random_uuid();
 job uuid;lease uuid:=gen_random_uuid();lease2 uuid:=gen_random_uuid();lease3 uuid:=gen_random_uuid();reply jsonb;report jsonb;batch jsonb;draft jsonb;legacy_exercise uuid;stamp timestamptz;before_bytes bigint;
begin
 insert into auth.users(id,email) values(actor,actor||'@media-video-cleanup.invalid');
 insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),actor,'totp','verified',now(),now());
 insert into auth.sessions(id,user_id,created_at,updated_at) values(sid,actor,now(),now());
 insert into public.trainer_access(trainer_id,enabled,client_limit,last_reason) values(actor,true,1,'Ensayo vídeos');
 claims:=jsonb_build_object('sub',actor,'session_id',sid,'aal','aal2','role','authenticated');
 perform set_config('request.jwt.claim.sub',actor::text,true);perform set_config('request.jwt.claims',claims::text,true);set local role authenticated;
 reserved:=public.reserve_exercise_video_upload('trainer_exercise',op,42,'fixture.b-cdn.net',1000);
 processing:=public.reserve_exercise_video_upload('trainer_exercise',gen_random_uuid(),42,'fixture.b-cdn.net',1000);
 ready:=public.reserve_exercise_video_upload('trainer_exercise',gen_random_uuid(),42,'fixture.b-cdn.net',1000);
 uncertain:=public.reserve_exercise_video_upload('trainer_exercise',gen_random_uuid(),42,'fixture.b-cdn.net',1000);
 uncertain_alias:=public.reserve_exercise_video_upload('trainer_exercise',gen_random_uuid(),42,'fixture.b-cdn.net',1000);
 perform set_config('request.jwt.claims',(claims||'{"role":"service_role"}')::text,true);set local role service_role;
 perform public.claim_exercise_video_creation(processing,create_claim);perform public.complete_exercise_video_creation(processing,create_claim,guid_a);
 update public.exercise_video_assets set status='processing' where id=processing;
 perform public.prepare_exercise_video_upload(processing,clock_timestamp()+interval '1 hour');
 perform public.claim_exercise_video_creation(ready,create_claim);perform public.complete_exercise_video_creation(ready,create_claim,guid_b);
 update public.exercise_video_assets set status='ready',duration_seconds=5,playback_bytes=1000,provider_storage_bytes=1000 where id=ready;
 begin perform public.prepare_exercise_video_upload(ready,clock_timestamp()+interval '1 hour');raise exception 'Reabre vídeo listo';exception when invalid_parameter_value then null;end;
 perform public.claim_exercise_video_creation(uncertain,create_claim);perform public.mark_exercise_video_creation_uncertain(uncertain,create_claim);
 perform public.claim_exercise_video_creation(uncertain_alias,create_claim);perform public.mark_exercise_video_creation_uncertain(uncertain_alias,create_claim);
 update public.exercise_video_assets set created_at=clock_timestamp()-interval '3 days',creation_guard_until=clock_timestamp()-interval '1 hour' where created_by=actor;
 reset role;update trainer_private.media_cleanup_settings set enabled=true;
 perform set_config('request.jwt.claims',claims::text,true);set local role authenticated;
 report:=public.sweep_exercise_media_cleanup(gen_random_uuid(),'trainer');
 if jsonb_array_length(report->'items')<>1 or(report->'items'->0->>'kind')<>'video' then raise exception 'El barrido elimina biblioteca lista, processing o incertidumbres';end if;
 job:=(report->'items'->0->>'job_id')::uuid;
 select(v->>'bytes_reserved')::bigint into before_bytes from jsonb_array_elements(public.get_trainer_video_usage())v where v->>'scope'='trainer_exercise';
 perform set_config('request.jwt.claims',(claims||'{"role":"service_role"}')::text,true);set local role service_role;
 batch:=public.claim_exercise_media_cleanup(3,actor,lease,'trainer');
 if jsonb_array_length(batch)<>1 or batch->0->>'creation_state'<>'reserved' or(batch->0->>'requires_reconciliation')::boolean then raise exception 'Reserva nunca creada no reconciliable';end if;
 reply:=public.finish_exercise_media_cleanup(job,lease,true);
 if public.finish_exercise_media_cleanup(job,lease,true)<>reply then raise exception 'ACK vídeo no idempotente';end if;
 reset role;perform set_config('request.jwt.claims',claims::text,true);set local role authenticated;
 if(select(v->>'bytes_reserved')::bigint from jsonb_array_elements(public.get_trainer_video_usage())v where v->>'scope'='trainer_exercise')<>before_bytes-104857600 then raise exception 'No libera exactamente reserva de vídeo';end if;
 begin perform public.reserve_exercise_video_upload('trainer_exercise',op,42,'fixture.b-cdn.net',1000);raise exception 'Resucita operación de vídeo eliminada';exception when invalid_parameter_value then null;end;
 reply:=public.queue_exercise_media_cleanup(gen_random_uuid(),'trainer','video',processing::text);
 if(reply->>'available_at')::timestamptz<clock_timestamp()+interval '59 minutes' then raise exception 'Ignora token de subida vigente';end if;
 perform set_config('request.jwt.claims',(claims||'{"role":"service_role"}')::text,true);set local role service_role;
 if public.claim_exercise_media_cleanup(3,actor,gen_random_uuid(),'trainer')<>'[]'::jsonb then raise exception 'Borra con token de subida vigente';end if;
 reset role;perform set_config('request.jwt.claims',claims::text,true);set local role authenticated;
 reply:=public.queue_exercise_media_cleanup(gen_random_uuid(),'trainer','video',uncertain::text);job:=(reply->>'job_id')::uuid;
 perform set_config('request.jwt.claims',(claims||'{"role":"service_role"}')::text,true);set local role service_role;
 batch:=public.claim_exercise_media_cleanup(3,actor,lease,'trainer');
 if jsonb_array_length(batch)<>1 or not(batch->0->>'requires_reconciliation')::boolean then raise exception 'Incertidumbre se considera ausencia';end if;
 begin perform public.finish_exercise_media_cleanup(job,lease,true,'reconciled_absent');raise exception 'Libera incierto sin identidad sellada';exception when invalid_parameter_value then null;end;
 begin perform public.resolve_exercise_media_cleanup_provider(job,gen_random_uuid(),guid_c);raise exception 'Resuelve con lease ajeno';exception when insufficient_privilege then null;end;
 reply:=public.resolve_exercise_media_cleanup_provider(job,lease,guid_c);
 if public.resolve_exercise_media_cleanup_provider(job,lease,guid_c)<>reply then raise exception 'Resolver mismo GUID no es idempotente';end if;
 begin perform public.resolve_exercise_media_cleanup_provider(job,lease,gen_random_uuid());raise exception 'Cambia identidad de proveedor';exception when invalid_parameter_value then null;end;
 perform public.finish_exercise_media_cleanup(job,lease,false,'external_ack_lost');
 reset role;update trainer_private.media_cleanup_jobs set available_at=clock_timestamp()-interval '1 minute' where id=job;
 perform set_config('request.jwt.claims',(claims||'{"role":"service_role"}')::text,true);set local role service_role;
 batch:=public.claim_exercise_media_cleanup(3,actor,lease2,'trainer');
 if not(batch->0->>'provider_identity_confirmed')::boolean or(batch->0->>'requires_reconciliation')::boolean or(batch->0->>'provider_video_id')::uuid<>guid_c then raise exception 'Pierde identidad tras respuesta externa perdida';end if;
 begin perform public.claim_exercise_video_creation(uncertain,gen_random_uuid());raise exception 'Recrea activo deleting';exception when invalid_parameter_value then null;end;
 begin update public.exercise_video_assets set status='processing' where id=uncertain;raise exception 'PATCH de servicio revive activo';exception when invalid_parameter_value then null;end;
 reset role;perform set_config('request.jwt.claims',claims::text,true);set local role authenticated;
 draft:=jsonb_build_object('name','Alias bloqueado','description','','video_url','https://fixture.b-cdn.net/'||guid_c::text||'/play_480p.mp4',
  'muscle_groups',jsonb_build_array('piernas'),'equipment',jsonb_build_array('ninguno'),'difficulty','inicial','exercise_type','repeticiones');
 begin perform public.save_trainer_exercise(gen_random_uuid(),draft);raise exception 'GUID reconciliado acepta referencia nueva';exception when invalid_parameter_value then null;end;
 reset role;update trainer_private.media_cleanup_jobs set lease_until=clock_timestamp()-interval '1 second' where id=job;
 perform set_config('request.jwt.claims',(claims||'{"role":"service_role"}')::text,true);set local role service_role;
 begin perform public.finish_exercise_media_cleanup(job,lease2,true);raise exception 'ACK con lease expirado';exception when insufficient_privilege then null;end;
 batch:=public.claim_exercise_media_cleanup(3,actor,lease3,'trainer');perform public.finish_exercise_media_cleanup(job,lease3,true);
 -- Una referencia con otra resolución aparece antes de conocer el GUID.
 reset role;perform set_config('request.jwt.claims',claims::text,true);set local role authenticated;
 legacy_exercise:=public.save_trainer_exercise(gen_random_uuid(),draft||jsonb_build_object('name','Alias legado','video_url','https://fixture.b-cdn.net/'||guid_d::text||'/play_480p.mp4'));
 reply:=public.queue_exercise_media_cleanup(gen_random_uuid(),'trainer','video',uncertain_alias::text);job:=(reply->>'job_id')::uuid;
 perform set_config('request.jwt.claims',(claims||'{"role":"service_role"}')::text,true);set local role service_role;
 batch:=public.claim_exercise_media_cleanup(3,actor,lease,'trainer');reply:=public.resolve_exercise_media_cleanup_provider(job,lease,guid_d);
 if reply->>'state'<>'blocked' or(reply->>'provider_identity_confirmed')::boolean then raise exception 'Borra alias descubierto al reconciliar';end if;
 reset role;
 if(select cleanup_state from public.exercise_video_assets where id=uncertain_alias)<>'active' then raise exception 'Deja lectura del medio protegido cerrada';end if;
 perform set_config('request.jwt.claims',claims::text,true);set local role authenticated;
 reply:=public.trash_trainer_catalog_item(gen_random_uuid(),'exercise',legacy_exercise);stamp:=(reply->>'trashed_at')::timestamptz;
 perform public.purge_trainer_catalog_item(gen_random_uuid(),'exercise',legacy_exercise,stamp);
 reply:=public.queue_exercise_media_cleanup(gen_random_uuid(),'trainer','video',uncertain_alias::text);
 if reply->>'state'<>'queued' then raise exception 'No permite reintentar tras quitar referencia';end if;
 perform set_config('request.jwt.claims',(claims||'{"role":"service_role"}')::text,true);set local role service_role;
 batch:=public.claim_exercise_media_cleanup(3,actor,lease2,'trainer');perform public.finish_exercise_media_cleanup(job,lease2,true);
 reset role;
 if not exists(select 1 from public.exercise_video_assets where id=ready and cleanup_state='active') then raise exception 'Elimina demostración lista suelta';end if;
 update trainer_private.media_cleanup_settings set ticket_hash=encode(sha256(convert_to(repeat('a',43),'UTF8')),'hex'),ticket_expires_at=clock_timestamp()+interval '50 seconds',ticket_used=false;
 perform set_config('request.jwt.claims',(claims||'{"role":"service_role"}')::text,true);set local role service_role;
 if not public.consume_exercise_media_cleanup_ticket(repeat('a',43)) or public.consume_exercise_media_cleanup_ticket(repeat('a',43)) then raise exception 'Ticket no es de un uso';end if;
 reset role;
end $$;
rollback;
